  void ConfirmSortie(){if(battle.Phase!=Phase.Preparation||battle.Wave!=0||(sortieField!=battle.FieldIndex&&battle.Units.Count!=0))return;if(sortieField!=battle.FieldIndex)OpenField(sortieField);if(battle.Mode==BattleMode.Reinforcement&&!sortieReinforcement&&!battle.DisableReinforcements())return;if(battle.Mode!=BattleMode.Reinforcement){if(!battle.SetDifficulty(sortieDifficulty))return;if(sortieReinforcement&&!battle.EnableReinforcements())return;}SavePreference();fieldMenu=false;notice=battle.Field.Name+" · "+(sortieReinforcement?"증원 전투":sortieDifficulty==2?"극한":sortieDifficulty==1?"도전":"기본")+" 난도";if(sortieSupply){int completed=0;for(int i=0;i<Balance.Fields.Length;i++)if(Cleared(i)||Cleared(i,true)||Cleared(i,true,true))completed++;completed=Math.Min(completed,Balance.MaxSupplyFields);if(completed>0&&battle.GrantSupply(completed*20)){notice+=" · 보급 +"+battle.SupplyBonus+"G";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer){if(Application.absoluteURL.Contains("fx-smoke=bestread"))Debug.Log("BEST_SUPPLY_APPLIED "+battle.SupplyBonus);if(Application.absoluteURL.Contains("fx-smoke=sortie"))Debug.Log("SORTIE_SUPPLY_APPLIED "+battle.SupplyBonus+" "+battle.Gold);}}}if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&(Application.absoluteURL.Contains("fx-smoke=sortie")||Application.absoluteURL.Contains("fx-smoke=remember-sortie")))Debug.Log("SORTIE_CONFIRMED "+battle.FieldIndex+" "+sortieDifficulty+" "+(battle.Mode==BattleMode.Reinforcement));}
  void FieldMap(Rect r,FieldDef field){Box(r,new Color(.25f,.39f,.22f,1));float sx=r.width/1280f,sy=r.height/768f;for(int i=0;i<field.Points.Length;i++){Point a=field.Points[i],b=field.Points[(i+1)%field.Points.Length];float ax=r.x+(float)a.X*sx,ay=r.y+(float)a.Y*sy,bx=r.x+(float)b.X*sx,by=r.y+(float)b.Y*sy;float minX=Mathf.Min(ax,bx),minY=Mathf.Min(ay,by);Box(new Rect(minX-3,minY-3,Mathf.Abs(bx-ax)+6,Mathf.Abs(by-ay)+6),new Color(.75f,.65f,.43f,1));}Box(new Rect(r.x+(float)field.Castle.X*sx,r.y+(float)field.Castle.Y*sy,Mathf.Max(5,(float)field.CastleWidth*sx),Mathf.Max(5,(float)field.CastleHeight*sy)),new Color(.55f,.78f,.84f,1));}
  void OpenField(int fieldIndex){if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&(Application.absoluteURL.Contains("fx-smoke=win")||Application.absoluteURL.Contains("fx-smoke=menufield")))Debug.Log("RESULT_OPEN_FIELD "+fieldIndex);int difficulty=battle.HardWaves?2:battle.FastWaves?1:0;bool reinforcement=battle.Mode==BattleMode.Reinforcement;autoOwned=false;checkpoint=null;waveCheckpoint=null;battle=Battle.CreateForRules(1,fieldIndex,FreshRulesVersion);BindBattle();battle.SetDifficulty(difficulty);if(reinforcement)battle.EnableReinforcements();SavePreference();visuals.Clear();selected=-1;inspectedEnemy=-1;paused=false;aiming=false;branchMenu=false;emberBranchMenu=false;toolsMenu=false;fieldMenu=false;guideMenu=false;newRecord=false;newSupply=false;newBest=false;newReinforcement=false;recordFailed=false;queued=null;earlyUntil=0;surrenderUntil=0;panelScroll=Vector2.zero;SimulationSpeed=1;notice=battle.Field.Name+" · 새 준비 "+battle.Field.StartGold+"G. 병력을 배치하세요.";}
