  string SaveButtonLabel(bool prep){int feedback=prep?prepSaveFeedback:saveFeedback;float successUntil=prep?prepSaveSuccessUntil:saveSuccessUntil;return !prep&&Time.unscaledTime<saveBlockedUntil&&(aiming||queued.HasValue)?"조준 취소 필요":feedback==2?"저장 실패 · 재시도":feedback==1&&Time.unscaledTime<successUntil?"저장 완료":prep?"준비 저장":"전투 저장";}
  bool SaveButton(Rect rect,bool prep,bool menu,bool enabled){Color previous=GUI.backgroundColor;int oldFont=button.fontSize;bool oldWrap=button.wordWrap;RectOffset oldPadding=button.padding;button.wordWrap=false;button.padding=new RectOffset(3,3,oldPadding.top,oldPadding.bottom);int feedback=prep?prepSaveFeedback:saveFeedback;bool blocked=!prep&&Time.unscaledTime<saveBlockedUntil&&(aiming||queued.HasValue);string label=!blocked&&feedback==2&&rect.width<140?"실패 · 재시도":SaveButtonLabel(prep);if(menu&&Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=prep-savefail")&&Time.unscaledTime>=debugManualFeedbackNext){debugManualFeedbackNext=Time.unscaledTime+1;Debug.Log("SAVE_SLOT_LABEL "+(prep?"prep ":"combat ")+label);}if(menu&&feedback==2&&!blocked&&Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=manual-savefail")&&Time.unscaledTime>=debugManualFeedbackNext){debugManualFeedbackNext=Time.unscaledTime+2;Debug.Log("MANUAL_SAVE_BUTTON_FAILURE "+label);}if(menu&&blocked&&Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&(Application.absoluteURL.Contains("fx-smoke=save-aim")||Application.absoluteURL.Contains("fx-smoke=save-queued"))&&Time.unscaledTime>=debugManualFeedbackNext){debugManualFeedbackNext=Time.unscaledTime+2;Debug.Log("SAVE_BLOCKED_BUTTON "+label);}while(button.fontSize>10&&MeasureText(button,label).x>rect.width-6)button.fontSize--;if(feedback==2&&!blocked)GUI.backgroundColor=previous*new Color(1f,.58f,.5f,1f);bool clicked=menu?MenuButton(rect,label,enabled):Button(rect,label,enabled);GUI.backgroundColor=previous;button.fontSize=oldFont;button.wordWrap=oldWrap;button.padding=oldPadding;return clicked;}
  void SavePrep(){try{if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=prep-savefail")&&!debugManualSaveFailureInjected){debugManualSaveFailureInjected=true;throw new InvalidOperationException("Injected preparation save failure");}PreparationStore.Save(battle);SaveFeedback(true);notice="현재 준비를 저장했습니다.";}catch(Exception){SaveFeedback(false);notice="준비를 저장하지 못했습니다. 현재 전투는 그대로 유지됩니다.";}}
  void SaveCurrent(){if(battle.Phase==Phase.Preparation){SavePrep();return;}if(battle.Phase!=Phase.Fighting)return;if(aiming||queued.HasValue){saveBlockedUntil=Time.unscaledTime+4;notice="잔불 조준이나 예약을 마친 뒤 저장하세요.";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&(Application.absoluteURL.Contains("fx-smoke=save-aim")||Application.absoluteURL.Contains("fx-smoke=save-queued")))Debug.Log("SAVE_BLOCKED_AIM");return;}try{if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=manual-savefail")&&!debugManualSaveFailureInjected){debugManualSaveFailureInjected=true;throw new InvalidOperationException("Injected manual save failure");}CombatStore.Save(battle,waveCheckpoint,(int)SimulationSpeed);SaveFeedback(true);autoSaveWarning=false;notice="전투를 저장했습니다 · 시작 화면에서 이어하기";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=wave-savefail"))Debug.Log("WAVE_SAVE_WARNING_CLEARED");}catch(Exception){SaveFeedback(false);notice="전투 저장에 실패했습니다. 저장 상태를 확인하세요.";}}
  bool LoadCombat(bool automatic=false){try{Battle loaded,savedWave;int speed;if(automatic)CombatStore.LoadAuto(out loaded,out savedWave,out speed);else CombatStore.Load(out loaded,out savedWave,out speed);autoOwned=automatic;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&automatic)Debug.Log("AUTO_LOAD "+loaded.Wave+" "+loaded.Gold+" "+CombatStore.Exists);checkpoint=null;waveCheckpoint=savedWave;battle=loaded;BindBattle();visuals.Clear();selected=-1;inspectedEnemy=-1;paused=true;aiming=false;queued=null;earlyUntil=0;panelScroll=Vector2.zero;SimulationSpeed=speed;notice=battle.RulesVersion<3?"이전 난도 규칙의 전투를 복원했습니다.":"전투 복원 완료 · 이어가기를 누르세요.";return true;}catch(Exception){notice="전투 저장을 읽지 못했습니다. 현재 상태는 그대로 유지됩니다.";return false;}}
  bool LoadPrep(){try{Battle saved=PreparationStore.Load();checkpoint=null;waveCheckpoint=null;battle=saved;BindBattle();visuals.Clear();selected=-1;inspectedEnemy=-1;paused=false;aiming=false;queued=null;SimulationSpeed=1;notice="저장한 준비를 불러왔습니다.";return true;}catch(Exception){notice="저장된 준비를 읽지 못했습니다. 현재 상태는 그대로 유지됩니다.";return false;}}
  void RetryCheckpoint(){if(checkpoint==null&&waveCheckpoint==null)return;try{bool combat=waveCheckpoint!=null;battle=combat?waveCheckpoint.CopyCombat():Battle.RestorePreparation(checkpoint);BindBattle();visuals.Clear();selected=-1;inspectedEnemy=-1;paused=combat;aiming=false;queued=null;earlyUntil=0;panelScroll=Vector2.zero;SimulationSpeed=1;notice=combat?battle.Wave+"웨이브 시작으로 복원 · 편성 후 이어가세요.":"시작 준비로 복원 · 병력을 조정하고 시작하세요.";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=surrender")&&combat&&paused)Debug.Log("SURRENDER_RETRY_OK");}catch(Exception){notice="최근 상태를 복원하지 못했습니다. 새 전투로 다시 시작하세요.";}}
