  string EarlyLabel(){return earlyUntil>Time.realtimeSinceStartup?"한 번 더 호출":"다음 호출 +"+battle.EarlyBonus()+"G";}
  void EarlyAction(){if(!EarlyAvailable())return;float now=Time.realtimeSinceStartup;if(earlyUntil>now){if(now<earlyReadyAt)return;int bonus=battle.EarlyBonus();if(battle.CallEarly()){if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=earlybutton"))Debug.Log("EARLY_BUTTON_CALLED");notice="다음 웨이브 호출 · 추가 "+bonus+"G";}earlyUntil=0;}else{int next=0;foreach(var group in battle.WaveGroups(battle.Wave))next+=battle.SpawnCount(group);earlyReadyAt=now+.3f;earlyUntil=now+4;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=earlybutton"))Debug.Log("EARLY_BUTTON_ARMED "+next);notice="현재 "+battle.Enemies.Count+"명 + 다음 "+next+"명."+(battle.Enemies.Count+next>=Balance.MaxAlive?" 100마리 도달 위험!":"")+" 4초 안에 다시 눌러 호출.";}}
  void ToggleChallenge(){int next=battle.HardWaves?0:battle.FastWaves?2:1;if(battle.SetDifficulty(next)){SavePreference();notice=battle.HardWaves?"극한 · 18초 간격, 적 체력 +80%":battle.FastWaves?"도전 · 22초 간격, 적 체력 +50%":"기본 모드 · 32초마다 웨이브";}}
