  void Arm(){if(battle.Phase==Phase.Fighting&&battle.EmberCD<=0){earlyUntil=0;aiming=true;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=emberbutton"))Debug.Log("EMBER_BUTTON_ARMED");notice="조준: 전장 클릭 또는 방향키 · Enter 확정 · Esc 취소";}else notice="잔불은 전투 중 재사용 대기 후 사용할 수 있습니다.";}
  void Fire(){if(!aiming)return;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=emberbutton"))Debug.Log("EMBER_BUTTON_FIRE");if(paused){queued=aim;notice="잔불 위치 예약. 직접 이어가면 한 번 발동합니다.";}else notice=battle.Ember(aim)?"잔불을 사용했습니다.":"잔불을 사용할 수 없습니다.";aiming=false;}
  float ResultScale(){return LargeSide()?Mathf.Min(2.6f,1.3f*Screen.height/720f):(Screen.width>=900&&768*scale>=260?1.3f:1);}
  Rect PauseResumeRect(){float factor=ResultScale(),boardWidth=1280*scale,width=Mathf.Min(360*factor,Mathf.Max(150,boardWidth-20)),x=ox+(boardWidth-width)/2,y=oy+Mathf.Max(8,768*scale*.60f-24);return new Rect(x,y,width,52*factor);}
  bool escapeHeld;
  void InputEvent(){var e=Event.current;if(HandleWarningFixture(e))return;if(e.keyCode==KeyCode.Escape){if(e.type==EventType.KeyUp)escapeHeld=false;else if(e.type==EventType.KeyDown){if(escapeHeld){e.Use();return;}escapeHeld=true;}}if(HandleSlotMenuInput(e))return;
   if(e.type==EventType.KeyDown&&e.keyCode==KeyCode.Escape&&!titleMenu&&!aiming&&!queued.HasValue&&!branchMenu&&!toolsMenu&&!fieldMenu&&!guideMenu){OpenTools();e.Use();return;}
   hoverSlot=-1;if(menuSlot<0&&!aiming&&!branchMenu&&!toolsMenu&&!fieldMenu&&!guideMenu&&(battle.Phase==Phase.Preparation||battle.Phase==Phase.Fighting)){Point hp=Map(e.mousePosition);if(OnMap(hp)){double nearest=Screen.width<700?Math.Max(36,20/scale):36;for(int i=0;i<battle.Field.Slots.Length;i++){double d=Point.Distance(hp,battle.Field.Slots[i]);if(d<nearest&&battle.At(i)==null){nearest=d;hoverSlot=i;}}}}
   if(e.keyCode==KeyCode.F11&&DesktopPlayer){if(e.type==EventType.KeyUp){held.Remove(KeyCode.F11);e.Use();return;}if(e.type==EventType.KeyDown){if(held.Add(KeyCode.F11))WindowMode();e.Use();return;}}
   if(WindowTooSmall()){if(e.type==EventType.KeyUp)held.Remove(e.keyCode);return;}
