  const string GuideText="목표: 적이 동시에 100마리가 되기 전에 모든 웨이브를 막으세요. 적은 길을 돌아도 사라지지 않습니다.\n\n배치와 강화: 빈 자리를 누르면 메뉴만 열립니다. 메뉴에서 병과를 선택하거나 카드를 빈 자리로 끌어 놓아 배치하세요. 병력을 누른 채 강화 쪽으로 끌어 놓아도 선택됩니다. 판매는 아래쪽이며 전투 중에는 재확인이 필요합니다.\n\n병과: 검사는 근접, 궁수는 원거리, 화약병은 범위 공격을 맡습니다. 빙결사는 적을 늦추고 대장장이는 주변 공격을 돕습니다. 대장장이의 속도 지원은 중복되지 않으며 가장 높은 값만 적용됩니다. 선택 정보의 범위는 주변 공격병 수, 추가는 그 대장장이를 제외하면 지원 효과가 낮아지는 공격병 수입니다. 추가 0명은 다른 대장장이와 겹치거나 현재 지원할 병력이 없다는 뜻입니다. 화약병은 붉은 원 안을 공격하지 못합니다.\n\n전투: 병력의 배치·강화·분기와 전술 조합으로 위기에 대응하세요. 잔불 수동 스킬은 현재 플레이에서 제외했습니다. P는 정지, Esc는 메뉴, Enter는 시작입니다. 적을 누르면 상태를 볼 수 있습니다. 적이 적을 때 다음 호출을 누르면 추가 골드를 받고 다음 웨이브가 빨리 옵니다. 마지막 적이 모두 등장하면 빠른 소탕을 선택할 수 있습니다.\n\n난도와 적: 다음 웨이브는 최소 32·22·18초 뒤에 오며, 이전 적의 등장이 끝나야 합니다. 도전에서는 궁수가 질주병과 방패병에 유리합니다. 폭약병은 주변을 기절시키고 대장은 돌진과 보호 함성을 사용합니다.\n\n증원 전투: 기본 난도로 전장 하나를 완료하면 출정 준비에서 선택할 수 있습니다. 도전보다 일반 적이 더 촘촘하게 나오며, 3웨이브와 6웨이브 전에 카드 세 장 중 하나를 선택합니다. 선택한 효과는 이번 전투에 유지되고 선택 중 자동 저장됩니다. 정밀 조준은 검사를 포함한 모든 공격 병력의 사거리를 늘리며 대장장이의 지원 범위는 늘리지 않습니다.\n\n저장과 기록: 웨이브 시작과 정리 시 자동 저장됩니다. 시작 창에서 전투를 이어갈 수 있고, 불러오면 정지 상태입니다. 여유 배지는 최대 동시 적 수가 전장의 기준 이하일 때, 조합 배지는 검사·궁수·화약병·빙결사 중 세 병과 이상이 적을 처치했을 때 얻습니다. 증원 전투는 배지 없이 최고 기록을 따로 저장합니다. 이전 규칙 기록은 별도로 표시됩니다.";

  string cachedGuide;float cachedGuideWidth=-1;int cachedGuideFont;
  string WrappedGuide(float width){if(cachedGuide!=null&&Mathf.Approximately(cachedGuideWidth,width)&&cachedGuideFont==menuNotice.fontSize)return cachedGuide;var output=new System.Text.StringBuilder();string line="";foreach(char ch in GuideText){if(ch=='\n'){output.Append(line).Append('\n');line="";continue;}string next=line+ch;if(line.Length>0&&MeasureText(menuNotice,next).x>width){if((ch=='.'||ch==',')&&line.Length>1){output.Append(line.Substring(0,line.Length-1)).Append('\n');line=line.Substring(line.Length-1)+ch;}else{output.Append(line.TrimEnd()).Append('\n');line=char.IsWhiteSpace(ch)?"":ch.ToString();}}else line=next;}output.Append(line);string[] lines=output.ToString().Split('\n');for(int i=1;i<lines.Length;i++){if(lines[i].Length>0&&lines[i].Length<=2&&(i==lines.Length-1||lines[i+1].Length==0)&&lines[i-1].Length>5){int cut=lines[i-1].Length-2;lines[i]=lines[i-1].Substring(cut)+lines[i];lines[i-1]=lines[i-1].Substring(0,cut);}}cachedGuide=string.Join("\n",lines);cachedGuideWidth=width;cachedGuideFont=menuNotice.fontSize;if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=guideend"))Debug.Log("GUIDE_WRAP_LINES "+cachedGuide.Replace("\n","|"));return cachedGuide;}
