  string BranchTitle(int kind,int branch){string[] first={"회전베기","연사","대형 폭약","혹한","넓은 작업장"};string[] second={"갑옷 파쇄","저격","화상","빙결","정밀 연마"};return branch==1?first[kind]:second[kind];}
  string BranchStats(Unit u,int branch){var d=Balance.Troops[u.Kind];if(u.Kind==0&&branch==1)return "대상 "+d.Targets+" → 5명";if(u.Kind==2&&branch==1)return "폭발 반경 "+d.Radius+" → 75";if(u.Kind==2)return "화상 없음 → 초당 8\n3초간 지속";if(u.Kind==3&&branch==1)return "둔화 35% → 50%";if(u.Kind==3)return "다섯 번째 공격\n1초 빙결 추가";if(u.Kind==4&&branch==1)return "지원 범위 "+Battle.UnitRange(u)+" → 220";if(u.Kind==4)return "주변 피해 증가\n없음 → 20%";double before,oldInterval,after,newInterval;battle.AttackStats(u,out before,out oldInterval);var preview=new Unit{Kind=u.Kind,Slot=u.Slot,Level=3,Branch=branch};battle.AttackStats(preview,out after,out newInterval);if(u.Kind==0)return "피해 "+Math.Round(before,1)+" → "+Math.Round(after,1)+"\n방어 무시";if(branch==1)return "간격 "+Math.Round(oldInterval,2)+" → "+Math.Round(newInterval,2)+"초";return "사거리 "+Math.Round(battle.AttackRange(u))+" → "+Math.Round(battle.AttackRange(preview))+"\n피해 "+Math.Round(before,1)+" → "+Math.Round(after,1)+"\n대장 +50%";}
