  string ReinforcementLabel(int card){switch(card){case ReinforcementDraft.ArcherHaste:return "궁수 훈련 · 공격 속도 +20%";case ReinforcementDraft.BombRadius:return "화약 보강 · 폭발 범위 +25%";case ReinforcementDraft.SwordTargets:return "검술 훈련 · 공격 대상 +1";case ReinforcementDraft.EmberCooldown:return "잔불 재사용 단축 · 대기 시간 -30%";case ReinforcementDraft.GoldIncome:return "전리품 · 획득 골드 +15%";case ReinforcementDraft.Range:return "정밀 조준 · 공격 사거리 +7%";case ReinforcementDraft.SwordDamage:return battle.HasNormalCards?"검날 강화 · 검사 피해 +8%":"검날 강화 · 검사 피해 +15%";default:return "알 수 없는 증원";}}
  string ReinforcementChange(int card){int count=battle.Reinforcements.Count(card);if(card==ReinforcementDraft.EmberCooldown)return (Balance.EmberCooldown*Math.Pow(.7,count)).ToString("0.#",System.Globalization.CultureInfo.InvariantCulture)+"초 → "+(Balance.EmberCooldown*Math.Pow(.7,count+1)).ToString("0.#",System.Globalization.CultureInfo.InvariantCulture)+"초";if(card==ReinforcementDraft.SwordTargets)return "+"+count+"→+"+(count+1);double multiplier=card==ReinforcementDraft.ArcherHaste?1.2:card==ReinforcementDraft.BombRadius?1.25:card==ReinforcementDraft.EmberCooldown?.7:card==ReinforcementDraft.Range?1.07:card==ReinforcementDraft.SwordDamage&&battle.HasNormalCards?1.08:1.15;return "×"+Math.Pow(multiplier,count).ToString("0.##",System.Globalization.CultureInfo.InvariantCulture)+"→×"+Math.Pow(multiplier,count+1).ToString("0.##",System.Globalization.CultureInfo.InvariantCulture);}
