  void ReinforcementPanel(){if(!battle.ReinforcementPending||toolsMenu||guideMenu||fieldMenu)return;if(battle.HasNormalCards){TacticalPanel();return;}float width=Math.Min(Screen.width-24,480),height=Math.Min(Screen.height-16,waveStartSaveFailed?284:260),x=(Screen.width-width)/2,y=(Screen.height-height)/2;Box(new Rect(0,0,Screen.width,Screen.height),new Color(0,0,0,.78f));UiPlate(new Rect(x,y,width,height));UiTitle(new Rect(x+12,y+4,width-24,34),"증원 선택",title);int old=button.fontSize;bool wrap=button.wordWrap;button.fontSize=Screen.width<400?12:15;button.wordWrap=false;int[] options=ActiveTacticalChoices();for(int i=0;i<options.Length;i++){int card=options[i];string label=ReinforcementLabel(card)+"  "+ReinforcementChange(card);int optionSize=button.fontSize;while(button.fontSize>10&&MeasureText(button,label).x>width-52)button.fontSize--;if(MenuButton(new Rect(x+20,y+48+i*58,width-40,50),label)&&battle.ChooseReinforcement(card)){waveClearUntil=0;sound.Play("wave");notice="증원 선택 · "+ReinforcementLabel(card);if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=reinforcement"))Debug.Log("REINFORCEMENT_CHOSEN "+card+" "+battle.Wave);}button.fontSize=optionSize;}if(waveStartSaveFailed){button.fontSize=11;string retryLabel="저장 실패 · 다시 저장 (선택 가능)";while(button.fontSize>10&&MeasureText(button,retryLabel).x>width-52)button.fontSize--;Color retryColor=GUI.backgroundColor;GUI.backgroundColor=retryColor*new Color(1f,.52f,.45f,1f);Box(new Rect(x+18,y+222,width-36,36),uiPrimary);bool retryClicked=MenuButton(new Rect(x+20,y+224,width-40,32),retryLabel);GUI.backgroundColor=retryColor;if(retryClicked){try{CombatStore.SaveAuto(battle,waveCheckpoint,(int)SimulationSpeed);waveStartSaveFailed=false;autoSaveWarning=false;autoOwned=true;autoSaveRetry.Success();notice="증원 선택을 자동 저장했습니다.";if(Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=savefail"))Debug.Log("REIN