  void WaveBanner(){if(battle.Phase!=Phase.Fighting||paused||aiming||branchMenu||toolsMenu||guideMenu)return;string line="";bool clearNotice=battle.Decided&&decidedUntil>Time.unscaledTime;bool clearEmphasis=clearNotice&&decidedUntil-Time.unscaledTime>2;if(clearNotice&&Debug.isDebugBuild&&Application.platform==RuntimePlatform.WebGLPlayer&&Application.absoluteURL.Contains("fx-smoke=quickclear")){int phase=clearEmphasis?2:1;if(phase!=debugClearBannerPhase){debugClearBannerPhase=phase;Debug.Log("QUICK_CLEAR_BANNER "+phase);}}if(clearNotice)line=clearEmphasis?(Screen.width<480?"마지막 적! "+battle.Enemies.Count+"명 소탕":"마지막 적 등장! 남은 "+battle.Enemies.Count+"명 소탕"):"남은 "+battle.Enemies.Count+"명 · 최대 "+battle.PeakAlive;else if(waveClearUntil>Time.unscaledTime)line="웨이브 정리!";else if(battle.WaveTime<2.5){bool boss=false;foreach(var group in battle.WaveGroups(battle.Wave-1))if(group.Kind==4)boss=true;line=battle.Wave+" 웨이브"+(boss?" · 대장 웨이브":" 시작");}else if(battle.UpcomingBoss&&battle.NextWaveIn<=8)line=battle.NextWaveIn<=0&&battle.Pending>0?"대장 전 적 등장 중":"대장 웨이브까지 "+Math.Ceiling(battle.NextWaveIn)+"초";if(line.Length==0)return;float boardWidth=1280*scale,width=Mathf.Min(clearEmphasis?460:320,Mathf.Max(150,boardWidth-24)),x=ox+(boardWidth-width)/2,y=oy+Mathf.Max(5,8*scale),height=clearEmphasis&&Screen.width>=480?52:36;Rect banner=PlaceWarning(new Rect(x,y,width,height));if(banner.width<=0)return;x=banner.x;y=banner.y;ReserveWarning("wave",banner);UiPlate(banner);int prior=menuNotice.fontSize;TextAnchor alignment=menuNotice.alignment;menuNotice.fontSize=Screen.width<480?13:clearEmphasis?21:16;while(menuNotice.fontSize>10&&MeasureText(menuNotice,line).x>width-32)menuNotice.fontSize--;menuNotice.alignment=TextAnchor.MiddleCenter;GUI.Label(new Rect(x+16,y+2,width-32,height-4),line,menuNotice);menuNotice.alignment=alignment;menuNotice.fontSize=prior;}
  string CompactWaveAdvice(){if(battle.Wave>=battle.WaveCount)return battle.Phase==Phase.Fighting?"마지막 웨이브 · 적을 모두 처치하세요":"";int[] counts=new int[Balance.Enemies.Length];bool gate0=false,gate1=false;foreach(var group in battle.WaveGroups(battle.Wave)){counts[group.Kind]+=battle.SpawnCount(group);gate0|=group.Gate==0;gate1|=group.Gate==1;}string line="다음 "+(battle.Wave+1)+"웨이브";if(gate0&&gate1)line+=" · 양쪽 성문";else if(gate1)line+=" · 2번 성문";line+="\n";for(int i=0;i<counts.Length;i++)if(counts[i]>0)line+=Balance.Enemies[i].Name.Replace("고블린 대장","대장")+" "+counts[i]+"  ";if(battle.EnemyCountersActive&&(counts[1]>0||counts[2]>0))line+=counts[1]>0&&counts[2]>0?"\n질주 근접 반감 · 방패 폭발 반감":counts[1]>0?"\n질주 근접 반감 · 궁수 추천":"\n방패 폭발 반감 · 궁수 추천";else if(counts[4]>0)line+="\n대장 주의 · 화력 집중";else if(counts[2]>0)line+="\n방패 주의 · 궁수 배치";else if(counts[3]>0)line+="\n폭약 주의 · 기절 범위";else if(counts[1]>0)line+="\n질주 주의 · 빙결사 둔화";return line;}
