  void SlotRing(Point p,Color c){float size=Screen.width<=640?9:4;for(int i=0;i<24;i++){double a=i*Math.PI/12;float x=(float)(p.X+Math.Cos(a)*25),y=(float)(p.Y+Math.Sin(a)*25);if(Screen.width<=640)Box(new Rect(x-size/2-2,y-size/2-2,size+4,size+4),new Color(.07f,.16f,.12f,.8f));Box(new Rect(x-size/2,y-size/2,size,size),c);}}
  void RangeRing(Point p,double radius){float size=Mathf.Max(4f,4f/Mathf.Max(.01f,scale)),border=1f/Mathf.Max(.01f,scale);for(int i=0;i<96;i++){double a=i*Math.PI/48,x=p.X+Math.Cos(a)*radius,y=p.Y+Math.Sin(a)*radius;if(x<0||x>1280||y<0||y>768)continue;Box(new Rect((float)x-size/2-border,(float)y-size/2-border,size+2*border,size+2*border),new Color(.08f,.1f,.07f,.95f));Box(new Rect((float)x-size/2,(float)y-size/2,size,size),new Color(1f,.94f,.54f,1f));}}
  void Ring(Point p,double radius,Color c){for(int i=0;i<64;i++){double a=i*Math.PI/32,x=p.X+Math.Cos(a)*radius,y=p.Y+Math.Sin(a)*radius;if(x<2||x>1278||y<2||y>766)continue;Box(new Rect((float)x-2,(float)y-2,4,4),c);}}
